import{_ as r,C as n,o as t,c as o,a2 as a,b as l,w as i,a as c,E as d,a3 as u}from"./chunks/framework.XaTYfhfj.js";const A=JSON.parse('{"title":"14.1 Requirements & Capacity Estimation","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.1-requirements-and-estimation.md","filePath":"system-design/14.1-requirements-and-estimation.md"}'),m={name:"system-design/14.1-requirements-and-estimation.md"};function h(g,e,p,y,f,x){const s=n("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="_14-1-requirements-capacity-estimation" tabindex="-1">14.1 Requirements &amp; Capacity Estimation <a class="header-anchor" href="#_14-1-requirements-capacity-estimation" aria-label="Permalink to &quot;14.1 Requirements &amp; Capacity Estimation&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>System capacity estimation is the mathematical process of calculating the hardware, bandwidth, memory, database storage, and compute resources required to run an application based on anticipated user traffic and data volume. It transforms abstract business requirements into concrete technical specifications.</p><hr><h2 id="_2-requirements-specification-for-truthguard" tabindex="-1">2. Requirements Specification for TruthGuard <a class="header-anchor" href="#_2-requirements-specification-for-truthguard" aria-label="Permalink to &quot;2. Requirements Specification for TruthGuard&quot;">​</a></h2>',5)),(t(),l(u,null,{default:i(()=>[d(s,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20FunctionalReqs%20%5B%22Functional%20Requirements%22%5D%0A%20%20%20%20%20%20%20%20FR1%5B%22FR1%3A%20Image%2FText%20Deepfake%20Verification%20via%20Edge%22%5D%0A%20%20%20%20%20%20%20%20FR2%5B%22FR2%3A%20Optical%20Camera%20EXIF%20%26%20Tamper%20Auditing%22%5D%0A%20%20%20%20%20%20%20%20FR3%5B%22FR3%3A%20Scam%20Call%20%26%20SMS%20Phishing%20Triage%22%5D%0A%20%20%20%20%20%20%20%20FR4%5B%22FR4%3A%20Cryptographic%20Media%20Storage%20%26%20Custody%20Log%22%5D%0A%20%20%20%20%20%20%20%20FR5%5B%22FR5%3A%20Executive%20Credibility%20%26%20Bias%20Telemetry%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20NonFunctionalReqs%20%5B%22Non-Functional%20Requirements%22%5D%0A%20%20%20%20%20%20%20%20NFR1%5B%22NFR1%3A%20Latency%20%3C%201.5s%20for%20client%20audits%22%5D%0A%20%20%20%20%20%20%20%20NFR2%5B%22NFR2%3A%20Zero%20Cloud%20Evidence%20Transmission%22%5D%0A%20%20%20%20%20%20%20%20NFR3%5B%22NFR3%3A%20Availability%2099.9%25%20uptime%22%5D%0A%20%20%20%20%20%20%20%20NFR4%5B%22NFR4%3A%20Scalability%20100k%20DAU%20with%20serverless%22%5D%0A%20%20%20%20end%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h3><ul><li><strong>FR1</strong>: The system must evaluate images, text, and URLs for synthetic AI artifacts and cross-reference assertions against fact-checking databases ([<code>truthlence/src/pages/Index.tsx</code>](file:///Users/avishjain/avishjain9-repos/33-codealchemist/truthlence/src/pages/Index.tsx)).</li><li><strong>FR2</strong>: The system must parse EXIF metadata, identify camera make/model, check for GPS tags, and flag photo-editing software signatures ([<code>camara-temper/src/lib/fileAnalyzer.ts</code>](file:///Users/avishjain/avishjain9-repos/33-codealchemist/camara-temper/src/lib/fileAnalyzer.ts)).</li><li><strong>FR3</strong>: The system must classify phone call transcripts and SMS text for social engineering, urgency manipulation, and financial scam keywords ([<code>calldetection-sms-contentdetection/src/pages/CallDetection.tsx</code>](file:///Users/avishjain/avishjain9-repos/33-codealchemist/calldetection-sms-contentdetection/src/pages/CallDetection.tsx)).</li><li><strong>FR4</strong>: The system must provide cryptographic file ingestion, simulated multi-stage encryption progress, and immutable activity logging ([<code>mediavault 2/src/lib/mediavault-store.ts</code>](file:///Users/avishjain/avishjain9-repos/33-codealchemist/mediavault%202/src/lib/mediavault-store.ts)).</li><li><strong>FR5</strong>: The system must provide an executive credibility dashboard rendering radial gauges, MBFC tiers, and claim dispute lists ([<code>mainpage/src/components/VeritAIApp.tsx</code>](file:///Users/avishjain/avishjain9-repos/33-codealchemist/mainpage/src/components/VeritAIApp.tsx)).</li></ul><h3 id="non-functional-requirements" tabindex="-1">Non-Functional Requirements <a class="header-anchor" href="#non-functional-requirements" aria-label="Permalink to &quot;Non-Functional Requirements&quot;">​</a></h3><ul><li><strong>NFR1 (Low Latency)</strong>: Client-side cryptographic hashing and EXIF extraction must complete in under 50 milliseconds for typical image sizes (&lt;20MB). Remote Edge Function inference must return within 2.0 seconds.</li><li><strong>NFR2 (Evidence Privacy)</strong>: High-resolution media files submitted for optical tamper analysis must never be uploaded to external cloud servers; hashing and metadata extraction must occur strictly within the client browser sandbox.</li><li><strong>NFR3 (High Availability)</strong>: The master hub portal and core routing interfaces must achieve 99.9% availability.</li><li><strong>NFR4 (Security &amp; Integrity)</strong>: Cryptographic SHA-256 digests must be collision-resistant and tamper-evident across all custody records.</li></ul><hr><h2 id="_3-capacity-estimation-arithmetic" tabindex="-1">3. Capacity Estimation Arithmetic <a class="header-anchor" href="#_3-capacity-estimation-arithmetic" aria-label="Permalink to &quot;3. Capacity Estimation Arithmetic&quot;">​</a></h2><h3 id="assumptions-enterprise-soc-scale" tabindex="-1">Assumptions (Enterprise SOC Scale) <a class="header-anchor" href="#assumptions-enterprise-soc-scale" aria-label="Permalink to &quot;Assumptions (Enterprise SOC Scale)&quot;">​</a></h3><ul><li><strong>Daily Active Users (DAU)</strong>: 100,000 security analysts and journalists.</li><li><strong>Scans per User</strong>: Each analyst performs an average of 10 media or transcript evaluations per day.</li><li><strong>Total Daily Invocations</strong>: $100,000 \\times 10 = 1,000,000$ daily forensic scans.</li><li><strong>Read-to-Write Ratio</strong>: 1:1 (every submission triggers an evaluation and an audit log write).</li></ul><h3 id="throughput-calculations-requests-per-second-rps" tabindex="-1">Throughput Calculations (Requests Per Second - RPS) <a class="header-anchor" href="#throughput-calculations-requests-per-second-rps" aria-label="Permalink to &quot;Throughput Calculations (Requests Per Second - RPS)&quot;">​</a></h3><ul><li><strong>Seconds per Day</strong>: $86,400 \\text{ seconds}$.</li><li><strong>Average RPS</strong>: $$\\text{Average RPS} = \\frac{1,000,000 \\text{ requests}}{86,400 \\text{ s}} \\approx 11.57 \\text{ RPS}$$</li><li><strong>Peak Load Multiplier</strong>: Traffic in an enterprise SOC spikes during major news events or coordinated cyber campaigns by a factor of $4\\times$. $$\\text{Peak RPS} = 11.57 \\times 4 \\approx 46.3 \\text{ RPS}$$</li></ul><h3 id="bandwidth-ingress-estimation" tabindex="-1">Bandwidth &amp; Ingress Estimation <a class="header-anchor" href="#bandwidth-ingress-estimation" aria-label="Permalink to &quot;Bandwidth &amp; Ingress Estimation&quot;">​</a></h3><ul><li><strong>Average Text Payload (Transcripts &amp; URLs)</strong>: 2 KB.</li><li><strong>Daily Ingress for Text</strong>: $1,000,000 \\times 2 \\text{ KB} = 2 \\text{ GB/day}$.</li><li><strong>Average Client-Side Media Scanned (Local Only)</strong>: 5 MB per image (processed locally via Web Crypto API, consuming $0 \\text{ bytes}$ of cloud ingress).</li><li><strong>Network Ingress Bandwidth</strong>: $$\\text{Peak Ingress Bandwidth} = 46.3 \\text{ RPS} \\times 2 \\text{ KB} \\approx 92.6 \\text{ KB/s} \\text{ (Extremely efficient)}$$</li></ul><h3 id="storage-growth-estimation-postgresql-audit-logs" tabindex="-1">Storage Growth Estimation (PostgreSQL &amp; Audit Logs) <a class="header-anchor" href="#storage-growth-estimation-postgresql-audit-logs" aria-label="Permalink to &quot;Storage Growth Estimation (PostgreSQL &amp; Audit Logs)&quot;">​</a></h3><ul><li><strong>Record Size</strong>: Profile record = ~500 bytes. Forensic audit log entry = ~1 KB.</li><li><strong>Daily Storage Ingestion</strong>: $1,000,000 \\times 1 \\text{ KB} = 1 \\text{ GB/day}$.</li><li><strong>Annual Storage Growth</strong>: $$\\text{Annual Growth} = 1 \\text{ GB/day} \\times 365 = 365 \\text{ GB/year}$$</li><li><em>Conclusion</em>: Standard managed PostgreSQL instances easily accommodate several years of forensic records without sharding.</li></ul><h3 id="ai-token-volume-cost-arithmetic" tabindex="-1">AI Token Volume &amp; Cost Arithmetic <a class="header-anchor" href="#ai-token-volume-cost-arithmetic" aria-label="Permalink to &quot;AI Token Volume &amp; Cost Arithmetic&quot;">​</a></h3><ul><li><strong>Average Prompt Tokens</strong>: 1,200 tokens (system instructions + 5,000-character input slice).</li><li><strong>Average Completion Tokens</strong>: 300 tokens (structured JSON response with indicators).</li><li><strong>Total Daily Tokens</strong>: $1,000,000 \\times 1,500 \\text{ tokens} = 1.5 \\text{ Billion tokens/day}$.</li><li><strong>Monthly Cost with Semantic Caching (40% Cache Hit Rate)</strong>: <ul><li>Cache hits: $400,000 \\text{ scans/day} \\times $0 = $0$.</li><li>Billable scans: $600,000 \\text{ scans/day} \\times 1,500 \\text{ tokens} = 900 \\text{ Million tokens/day}$.</li><li>At an estimated blended rate of $$1.50 \\text{ per million tokens}$ (e.g., GPT-4o mini or Claude 3.5 Haiku): $$\\text{Daily Inference Cost} = 900 \\times $1.50 = $1,350/\\text{day} \\approx $40,500/\\text{month}$$</li></ul></li></ul><hr><h2 id="_4-architectural-alternatives-for-capacity-estimation" tabindex="-1">4. Architectural Alternatives for Capacity Estimation <a class="header-anchor" href="#_4-architectural-alternatives-for-capacity-estimation" aria-label="Permalink to &quot;4. Architectural Alternatives for Capacity Estimation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>TruthGuard Approach</th><th>Alternative A</th><th>Alternative B</th></tr></thead><tbody><tr><td><strong>Computation Layer</strong></td><td>Client-Side Cryptography (Web Crypto)</td><td>Centralized Server Hashing (Node.js)</td><td>Cloud Worker Farm (AWS Lambda)</td></tr><tr><td><strong>Ingress Bandwidth</strong></td><td>92 KB/s (Payload Metadata only)</td><td>231 MB/s (Transmitting 5MB files)</td><td>231 MB/s (S3 Direct Upload)</td></tr><tr><td><strong>Cloud Storage Cost</strong></td><td>Zero for raw media (Local/Client Drive)</td><td>Extreme (Petabytes of video/images)</td><td>Moderate (S3 Glacier Archive)</td></tr></tbody></table><hr><h2 id="_5-what-breaks-first-at-10x-100x-and-1-000x-load" tabindex="-1">5. What Breaks First at 10x, 100x, and 1,000x Load <a class="header-anchor" href="#_5-what-breaks-first-at-10x-100x-and-1-000x-load" aria-label="Permalink to &quot;5. What Breaks First at 10x, 100x, and 1,000x Load&quot;">​</a></h2><ul><li><strong>At 10x Load (115 RPS)</strong>: The client application and Supabase Edge Functions handle this seamlessly due to automated serverless scaling.</li><li><strong>At 100x Load (1,150 RPS)</strong>: Upstream AI inference rate limits will throttle requests (HTTP 429). Mitigate by introducing an Upstash Redis semantic cache and token bucket queue.</li><li><strong>At 1,000x Load (11,500 RPS)</strong>: PostgreSQL connection poolers (<code>pgbouncer</code>) will exhaust available connections on write spikes. Mitigate by sharding audit logs across multiple PostgreSQL read replicas and utilizing write-behind queues.</li></ul><hr><h2 id="_6-30-second-spoken-interview-answer" tabindex="-1">6. 30-Second Spoken Interview Answer <a class="header-anchor" href="#_6-30-second-spoken-interview-answer" aria-label="Permalink to &quot;6. 30-Second Spoken Interview Answer&quot;">​</a></h2><blockquote><p>&quot;For capacity estimation, we assumed an enterprise scale of 100,000 daily active analysts performing 10 scans each, yielding 1 million daily requests and a peak throughput of approximately 46 requests per second.</p><p>Because we process heavy image hashing and EXIF extraction entirely client-side using the Web Crypto API, our cloud ingress bandwidth is under 100 kilobytes per second.</p><p>Annual database storage growth is modest at around 365 gigabytes, while our biggest cost driver is AI token consumption, which we optimize using strict 5,000-character input slicing and semantic caching.&quot;</p></blockquote>',25))])}const v=r(m,[["render",h]]);export{A as __pageData,v as default};
